using System;using System.IO;using System.Linq;using System.Threading;using System.Threading.Tasks;using Musikbox;
class SearchCounter62{
 static int count;static void Check(bool ok,string why){if(!ok)throw new Exception(why);count++;Console.WriteLine("PASS "+why);}
 static void Main(string[] args){var glen=new Song{Artist="Glen Campbell",Title="Sunflower",Album="Country",Genre="Country",Year="1977",Source=Path.GetFullPath("glen.mp3")};var wilson=new Song{Artist="Lainey Wilson",Title="Heart Like A Truck",Album="Bell Bottom Country",Source=Path.GetFullPath("wilson.mp3")};var acdc=new Song{Artist="AC/DC",Title="Thunderstruck",Album="The Razors Edge",Source=Path.GetFullPath("acdc.mp3")};var library=new[]{glen,wilson,acdc};var folder=new BoxFolder{Name="Test"};var index=new LibrarySearchIndex(library.Select(s=>new LibrarySearchIndex.Entry(folder,s)));
 foreach(bool voice in new[]{false,true})foreach(var q in new[]{Tuple.Create("wilson",wilson),Tuple.Create("Glen Sun",glen),Tuple.Create("Campbell Glen",glen),Tuple.Create("ACDC",acdc),Tuple.Create("Sunflower",glen),Tuple.Create("country 1977",glen)})Check(index.Filter(q.Item1,voice,CancellationToken.None).Single().Song==q.Item2,(voice?"Sprache: ":"Tastatur: ")+q.Item1);
 Check(index.Filter("unbekannt Campbell",true,CancellationToken.None).Length==0,"Alle Fragmente erforderlich");Check(index.Filter("Glenn Campbel",true,CancellationToken.None).Single().Song==glen,"Phonetische Varianten");Check(index.Filter("Glen Kämpel",true,CancellationToken.None).Single().Song==glen,"Deutsche Aussprache");Check(index.Filter("Glen Sannflauer",true,CancellationToken.None).Single().Song==glen,"Englischer Titel mit deutscher Aussprache");
 Check(index.Filter("",false,CancellationToken.None).Length==3,"Leere Suche stellt Bibliothek wieder her");Check(index.Filter("xyzxyz",false,CancellationToken.None).Length==0,"Leeres Ergebnis");
 var counter=new LibraryCounter();foreach(var s in library)counter.Add(s);Check(counter.Snapshot().Titles==3&&counter.Snapshot().Albums==3&&counter.Snapshot().Artists==3,"Drei getrennte Zaehler");foreach(var s in library)counter.Add(s.Copy());Check(counter.Snapshot().Titles==3,"Wiederholter Import zaehlt dieselben Pfade einmal");var extra=new Song{Artist="Glen Campbell",Title="Rhinestone Cowboy",Album="Country",Source=Path.GetFullPath("extra.mp3")};counter.Add(extra);Check(counter.Snapshot().Titles==4&&counter.Snapshot().Artists==3&&counter.Snapshot().Albums==3,"Neue Datei mit bestehendem Album/Interpreten");
 Parallel.For(0,1000,i=>counter.Add(library[i%3]));Check(counter.Snapshot().Titles==4,"Nebenlaeufige doppelte Rueckmeldungen");Check(LibraryCounter.FromSongs(library.Concat(library)).Titles==3,"Tatsaechliche Bibliothekszahlen ohne Dubletten");
 var path=Path.Combine(Path.GetTempPath(),Guid.NewGuid()+".tsv");try{var personal=new VoiceCorrections(path);personal.Set("mein kampel","Glen Campbell");Check(index.Filter(new VoiceCorrections(path).Apply("mein kampel"),true,CancellationToken.None).Single().Song==glen,"Persoenliche Korrektur nach Neustart");personal.Remove("mein kampel");Check(new VoiceCorrections(path).Apply("mein kampel")=="mein kampel","Korrektur loeschen");}finally{File.Delete(path);}
 if(args.Length>0){var p=new Project();var progress=new LibraryCounter();int events=0;var result=DropImport.Read(p,new[]{args[0],args[0],Path.Combine(args[0],"glen.mp3")},-1,()=>{},FolderImportMode.PreserveStructure,null,true,s=>{progress.Add(s);events++;});Check(result.FilesAdded==3&&progress.Snapshot().Titles==3&&events>=3,"Echte MP3-Dateien: Ordner und mehrfach ausgewaehlte Datei");Check(LibraryCounter.FromSongs(result.Project.Folders.SelectMany(f=>f.Songs)).Titles==3,"Abschlusszahl entspricht Bibliothek");var again=new LibraryCounter();var repeat=DropImport.Read(result.Project,new[]{args[0]},-1,()=>{},FolderImportMode.PreserveStructure,null,true,s=>again.Add(s));Check(again.Snapshot().Titles==3&&LibraryCounter.FromSongs(repeat.Project.Folders.SelectMany(f=>f.Songs)).Titles==3,"Erneuter vollstaendiger Import ersetzt wie v0.61, ohne Aufsummieren");}
 Console.WriteLine("BESTANDEN: "+count+" Tests; gefuellter Metadatenkatalog, keine reale Windows-/Mikrofonpruefung.");
 }
}
